  const state = {lang:localStorage.getItem('sisp_lang')||'en', data:null, activeTrack:null, activeLesson:null, searchResults:[], assistantMode:'ai', admin:null, adminData:null, adminSection:'dashboard', editingContent:null, editingTeam:null, createLesson:false, member:null, accountMode:'signup', aiHistory:[], humanTimer:null, humanStaffTimer:null, humanThreadOpen:null, humanStaffOpen:null, humanStaffSeen:{}, humanNotificationCount:null};
