  const t=(key)=>translations[state.lang]?.[key]||translations.en[key]||key;
  const ht=(key)=>humanCopy[state.lang]?.[key]||humanCopy.en[key]||key;
  const chatPrivacyCopy=()=>state.lang==='fr'?'Si l’IA est activée, votre question et les derniers messages de cette conversation sont transmis au fournisseur configuré. Ses règles de confidentialité et de conservation s’appliquent. Le site ne conserve pas les transcriptions. N’indiquez ni nom, ni adresse, ni détail intime.':state.lang==='rw'?'AI ihujwe, ikibazo cyawe n’ubutumwa buheruka muri iki kiganiro byoherezwa ku itanga serivisi ryashyizweho. Amabwiriza yaryo yo kubika no kurinda amakuru arakurikizwa. Uru rubuga ntirubika inyandiko z’ibiganiro. Ntushyiremo izina, aderesi cyangwa amakuru y’ibanga.':'If AI is enabled, your question and recent chat messages are sent to the configured provider; that provider’s privacy and retention policies apply. The site does not store transcripts. Do not include a name, address or intimate detail.';
  const eyebrowText={en:{learning:'LEARNING CENTRE',services:'OUR SERVICES',help:'SAFETY & SUPPORT',resources:'SOURCE LIBRARY',about:'ABOUT',team:'OUR TEAM',contact:'CONTACT',donate:'DONATE',search:'DISCOVER',admin:'SECURE WORKSPACE'},rw:{learning:'AMASOMO',services:'SERIVISI ZACU',help:'UMUTEKANO N’UBUFASHA',resources:'AMASOKO Y’AMAKURU',about:'IBYEREKEYE',team:'ITSINDA',contact:'TWANDIKIRE',donate:'GUTERA INKUNGA',search:'SHAKISHA',admin:'AHABAKORA UBUYOBOZI'},fr:{learning:'CENTRE D’APPRENTISSAGE',services:'NOS SERVICES',help:'SÉCURITÉ ET SOUTIEN',resources:'BIBLIOTHÈQUE DE SOURCES',about:'À PROPOS',team:'NOTRE ÉQUIPE',contact:'CONTACT',donate:'FAIRE UN DON',search:'DÉCOUVRIR',admin:'ESPACE ADMINISTRATEUR'}};
  const eye=(key)=>eyebrowText[state.lang]?.[key]||eyebrowText.en[key];
