  async function humanStaffRefresh(){
    if(!state.admin||!document.getElementById('human-staff-area'))return;try{const current=state.humanStaffOpen;await fetchJson('/api/human/staff/presence',{method:'POST',body:JSON.stringify({thread_id:current?.threadId||'',typing:Boolean(current?.area?.value?.trim())})}).catch(()=>{});const data=await fetchJson('/api/human/staff/inbox'),queue=document.getElementById('human-waiting-list'),assigned=document.getElementById('human-assigned-list'),label=document.getElementById('human-staff-state');if(!queue||!assigned||!label)return;label.textContent=`${state.admin.role} · online · encrypted staff chat`;
      queue.replaceChildren();if(!data.waiting.length)queue.append(make('p','muted',ht('noWaiting')));data.waiting.forEach(item=>{const card=make('article','human-queue-card');card.append(make('strong','',`${ht('queued')} · ${item.language.toUpperCase()}`),make('p','muted',`${item.id.slice(0,8)} · ${new Date(item.created_at).toLocaleTimeString()}`),make('p','microcopy','Client identity and message stay encrypted until a support assistant accepts.'));const accept=btn(ht('accept'),'button button-primary button-small',async()=>{accept.disabled=true;try{await fetchJson('/api/human/staff/accept',{method:'POST',body:JSON.stringify({thread_id:item.id})});await humanStaffRefresh()}catch(err){humanBubble(card,err.message,'error')}finally{accept.disabled=false}});accept.disabled=state.admin.role!=='support_assistant';card.append(accept);queue.append(card)});
      assigned.replaceChildren();if(!data.assigned.length)assigned.append(make('p','muted',ht('noAssigned')));data.assigned.forEach(item=>{const card=make('article','human-queue-card');const lastClientId=Math.max(0,...(item.messages||[]).filter(message=>message.sender_type==='client').map(message=>Number(message.id)||0));const unread=lastClientId>(state.humanStaffSeen?.[item.id]||0);card.append(make('strong','',`${item.status==='paused'?'Paused':'Active'} · ${item.id.slice(0,8)}`),make('small','',`${item.client_typing?ht('clientTyping'):item.client_last_seen?`Client last active ${new Date(item.client_last_seen).toLocaleTimeString()}`:''} · ${item.language.toUpperCase()}`));const open=btn(unread?ht('newMessage'):'Open encrypted chat','button button-secondary button-small',async()=>{try{state.humanStaffSeen[item.id]=lastClientId;if(!state.humanStaffKey)state.humanStaffKey=await humanEnsureStaffKey();if(!item.wrapped_key)throw new Error('The encrypted key envelope is missing for this assigned chat.');const aesKey=await humanUnwrapKey(item.wrapped_key,state.humanStaffKey.privateKey);humanStaffChatView(document.getElementById('human-staff-chat'),item,{...state.humanStaffKey,aesKey},data.staff,data.admin_id)}catch(err){humanBubble(card,err.message,'error')}});card.append(open);assigned.append(card)});
      if(current){const active=data.assigned.find(item=>item.id===current.threadId);if(!active){state.humanStaffOpen=null;document.getElementById('human-staff-chat')?.replaceChildren()}else{current.status.textContent=`${active.client_last_seen&&Date.now()-Date.parse(active.client_last_seen)<45000?ht('online'):ht('offline')}${active.client_typing?` · ${ht('clientTyping')}`:''}`;await humanStaffRenderMessages(current.log,active.messages||[],current.aesKey,data.admin_id);state.humanStaffSeen[current.threadId]=Math.max(state.humanStaffSeen[current.threadId]||0,...(active.messages||[]).filter(message=>message.sender_type==='client').map(message=>Number(message.id)||0))}}
      const count=data.assigned.reduce((n,item)=>n+(item.messages||[]).filter(message=>message.sender_type==='client').length,0);if(state.humanNotificationCount!==null&&state.humanNotificationCount!==undefined&&count>state.humanNotificationCount&&'Notification'in window&&Notification.permission==='granted')new Notification(ht('newMessage'),{body:ht('newMessage')});state.humanNotificationCount=count;
    }catch(err){const label=document.getElementById('human-staff-state');if(label)label.textContent=err.message||ht('needKey')}
  }
  async function renderHumanStaff(area){if(state.humanStaffTimer){clearInterval(state.humanStaffTimer);state.humanStaffTimer=null}state.humanStaffOpen=null;area.id='human-staff-area';const panel=make('section','admin-panel');panel.append(make('h2','',ht('title')),make('p','muted',ht('keyLost')));const label=make('p','human-status',ht('setUp'));label.id='human-staff-state';const alerts=btn(ht('enableAlerts'),'button button-secondary button-small',async()=>{if(!('Notification'in window)){humanBubble(panel,'Browser alerts are not supported.','error');return}const result=await Notification.requestPermission();humanBubble(panel,result==='granted'?'Chat alerts are enabled.':'Browser alerts were not enabled.')});const waiting=make('section','human-staff-section');waiting.append(make('h3','',ht('waiting')));const queue=make('div','human-queue-list');queue.id='human-waiting-list';waiting.append(queue);const assigned=make('section','human-staff-section');assigned.append(make('h3','',ht('assigned')));const list=make('div','human-queue-list');list.id='human-assigned-list';assigned.append(list);const chat=make('div');chat.id='human-staff-chat';panel.append(label,alerts,waiting,assigned,chat);area.replaceChildren(panel);try{state.humanStaffKey=await humanEnsureStaffKey();label.textContent=ht('ready');state.humanNotificationCount=null;state.humanStaffSeen={};await humanStaffRefresh();state.humanStaffTimer=setInterval(humanStaffRefresh,4000)}catch(err){label.textContent=err.message||ht('needKey')}}

  async function humanClientScreen(content){
    humanStopPolling();content.replaceChildren(make('p','muted',ht('loading')));
    if(!globalThis.crypto?.subtle||!globalThis.indexedDB){content.replaceChildren(make('h3','',ht('title')),make('p','human-error',ht('unavailable')),anchor('/help',t('getHelp'),'help'));return}
    try{
      const [record,snapshot]=await Promise.all([humanKeyGet(HUMAN_CLIENT_KEY),fetchJson('/api/human/client/state')]);
      if(record&&snapshot.thread&&record.threadId===snapshot.thread.id){content.replaceChildren();humanClientChoice(content,snapshot.thread,record);return}
      if(snapshot.thread&&!record){content.replaceChildren(make('h3','',ht('title')),make('p','human-error',ht('keyLost')),btn(ht('startAi'),'button button-primary',()=>assistantMode('ai')));return}
      content.replaceChildren();humanStartForm(content);
    }catch(err){content.replaceChildren(make('p','human-error',err.message||ht('needKey')),anchor('/help',t('getHelp'),'help'))}
  }
  function assistantMode(mode){
    if(state.assistantMode==='human'&&mode!=='human'){humanCancelVoiceRecording();humanStopPolling();fetchJson('/api/human/client/pause',{method:'POST',body:'{}'}).catch(()=>{});fetchJson('/api/human/client/presence',{method:'POST',body:JSON.stringify({typing:false})}).catch(()=>{});humanClearMediaUrls()}
    state.assistantMode=mode;
    document.querySelectorAll('.mode-tabs button').forEach(b=>b.setAttribute('aria-selected',b.dataset.mode===mode?'true':'false'));
    const content=make('div','assistant-content');
    const host=document.getElementById('assistant-content');
    host.replaceWith(content);content.id='assistant-content';
    if(mode==='ai'){
      const log=make('div','chat-messages');log.id='chat-messages';log.setAttribute('aria-live','polite');
      state.aiHistory.slice(-8).forEach(item=>addChat(log,item.content,item.role==='user'?'user':'bot'));
      content.append(log);
      const form=make('form');form.id='chat-form';
      const area=make('textarea');area.id='chat-input';area.rows=2;area.maxLength=4000;area.placeholder=t('chatPlaceholder');area.setAttribute('aria-label',t('chatPlaceholder'));
      const submit=make('button','button button-primary',t('send'));submit.type='submit';
      form.append(area,submit);
      const examples={
        en:['What does consent mean?','How can I stay safer online?','How do I find a health service?'],
        rw:['Kwemeranya bisobanura iki?','Nakwirinda nte kuri interineti?','Nabona nte serivisi y’ubuzima?'],
        fr:['Que signifie le consentement ?','Comment être plus en sécurité en ligne ?','Comment trouver un service de santé ?']
      }[state.lang];
      if(!state.aiHistory.length){
        const suggestions=make('div','assistant-suggestions');
        examples.forEach(question=>{const choice=btn(question,'assistant-suggestion',()=>{area.value=question;area.focus()});suggestions.append(choice)});
        content.append(suggestions);
      }
      form.addEventListener('submit',async e=>{
        e.preventDefault();const message=area.value.trim();if(!message)return;
        addChat(log,message,'user');const prior=state.aiHistory.slice(-8);state.aiHistory=[...prior,{role:'user',content:message}].slice(-8);area.value='';area.disabled=true;submit.disabled=true;
        const wait=make('div','chat-message bot',state.lang==='en'?'One moment…':'…');log.append(wait);
        try{
          const result=await fetchJson('/api/ai',{method:'POST',body:JSON.stringify({language:state.lang,message,history:prior})});
          const answer=typeof result.answer==='string'?result.answer:result.answer?.[state.lang]||'';wait.textContent=answer;
          state.aiHistory=[...state.aiHistory,{role:'assistant',content:answer}].slice(-8);
          if(result.sources?.length){
            const sources=make('div','chat-sources');sources.append(make('strong','',({en:'Reviewed site sources',rw:'Amasoko yasuzumwe kuri uru rubuga',fr:'Sources du site examinées'})[state.lang]));
            result.sources.forEach(source=>{
              const href=typeof source==='string'?source:source.href;
              const label=typeof source==='string'?source:(source.title||source.slug);
              if(href){const link=anchor(href,label);if(/^https:\/\//.test(href)){link.target='_blank';link.rel='noopener noreferrer'}sources.append(link)}
            });
            wait.append(sources);
          }
          if(result.needs_review){const help=anchor('/help','See verified support options','help');help.className='text-link';wait.append(help)}
        }catch(err){wait.classList.add('error');wait.textContent=err.data?.error||t('aiUnavailable')}
        finally{area.disabled=false;submit.disabled=false;area.focus();log.scrollTop=log.scrollHeight}
      });
      content.append(form,make('p','microcopy',chatPrivacyCopy()));
    }else if(mode==='human'){
      humanClientScreen(content);
    }else{
      const card=make('div','mode-unavailable',t('voiceUnavailable'));
      content.append(card,anchor('/help',t('getHelp'),'help'));
    }
  }
  function addChat(log,text,kind){const m=make('div',`chat-message ${kind}`,text);log.append(m);log.scrollTop=log.scrollHeight;}
