  function adminLoginPage(){const wrap=make('div','page-shell');appendTitle(wrap,eye('admin'),t('adminTitle'),t('adminLead'));const card=make('section','admin-panel');const form=make('form','admin-form');const email=make('input');email.type='email';email.autocomplete='username';email.required=true;const password=make('input');password.type='password';password.autocomplete='current-password';password.required=true;const eField=make('div','form-field');eField.append(make('label','',t('email')));eField.lastChild.htmlFor='admin-email';email.id='admin-email';eField.append(email);const pField=make('div','form-field');const pl=make('label','',t('password'));pl.htmlFor='admin-password';password.id='admin-password';pField.append(pl,password);const error=make('p','error-text');error.hidden=true;const submit=make('button','button button-primary',t('signIn'));submit.type='submit';form.append(eField,pField,error,submit);form.addEventListener('submit',async e=>{e.preventDefault();error.hidden=true;try{const result=await fetchJson('/api/admin/login',{method:'POST',body:JSON.stringify({email:email.value,password:password.value})});state.admin=result.admin;await loadAdmin();render()}catch(err){error.textContent=err.message;error.hidden=false}});card.append(form,make('p','muted',state.lang==='en'?'Approved staff and the CEO use this sign-in. The CEO approves staff applications and assigns roles. There is no default password.':state.lang==='rw'?'':'Les identifiants sont fournis par l’organisation.'));wrap.append(card,anchor('/staff','Apply for a staff account','staff'));return wrap;}
