  function renderCreateLesson(area){const panel=make('section','admin-panel');panel.append(make('h2','', 'Add a lesson draft'));const form=make('form','admin-form');const slug=make('input');slug.required=true;slug.pattern='[a-z0-9]+(?:-[a-z0-9]+)*';slug.placeholder='lesson-topic';const language=make('select');[['en','English'],['rw','Kinyarwanda'],['fr','French']].forEach(([v,l])=>{const o=make('option','',l);o.value=v;language.append(o)});const track=make('select');state.data.tracks.forEach(item=>{const o=make('option','',`${item.ages} · ${item.title}`);o.value=item.id;track.append(o)});const title=make('input');title.required=true;title.maxLength=180;const summary=make('textarea');summary.required=true;summary.maxLength=600;summary.rows=3;const body=make('textarea');body.required=true;body.maxLength=20000;body.rows=9;[[`Lesson ID`,slug],[`Language`,language],[`Age pathway`,track],[`Title`,title],[`Short summary`,summary],[`Lesson text`,body]].forEach(([label,input])=>{const f=make('div','form-field');f.append(make('label','',label),input);form.append(f)});const feedback=make('p','muted');const actions=make('div','admin-actions');const save=make('button','button button-primary','Submit for professional review');save.type='submit';actions.append(save,btn('Cancel','button button-secondary',()=>{state.createLesson=false;render()}));form.append(feedback,actions);panel.append(form);form.addEventListener('submit',async e=>{e.preventDefault();feedback.textContent='Submitting…';try{const result=await fetchJson('/api/admin/content/create',{method:'POST',body:JSON.stringify({slug:slug.value,language:language.value,age_track:track.value,title:title.value,summary:summary.value,body:body.value})});state.createLesson=false;state.editingContent=result.id;await loadAdmin();render()}catch(err){feedback.textContent=err.message;feedback.className='error-text'}});area.append(panel);}
  function renderStaffAdmin(area){const requests=state.adminData.staff_requests||[];const panel=make('section','admin-panel');panel.append(make('h2','',`Pending staff applications (${requests.length})`));if(!requests.length)panel.append(make('p','muted','No applications are waiting for review.'));requests.forEach(item=>{const card=make('article','admin-item');card.classList.add('staff-request');const info=make('div');info.append(make('strong','',item.full_name),make('small','',`${item.email} · requested ${item.requested_role}${item.requested_position?` · ${item.requested_position}`:''}`));const controls=make('div','staff-review-controls');const role=make('select');[['educator','Educator'],['assistant','Support assistant'],['leadership','Leadership position']].forEach(([v,l])=>{const o=make('option','',l);o.value=v;o.selected=v===item.requested_role;role.append(o)});const position=make('select');(state.adminData.leadership_positions||[]).filter(p=>p.active).forEach(p=>{const o=make('option','',p.title);o.value=p.title;o.selected=p.title===item.requested_position;position.append(o)});position.hidden=role.value!=='leadership';role.addEventListener('change',()=>position.hidden=role.value!=='leadership');const approve=btn('Confirm name & approve role','button button-primary button-small',async()=>{try{if(role.value==='leadership'&&!position.value)throw new Error('Create a leadership position first.');await fetchJson('/api/admin/staff/requests',{method:'POST',body:JSON.stringify({id:item.id,action:'approve',approved_role:role.value,approved_position:position.value})});await loadAdmin();render()}catch(err){notice(err.message)}});const reject=btn('Reject','button button-secondary button-small',async()=>{if(!confirm(`Reject the application from ${item.full_name}?`))return;try{await fetchJson('/api/admin/staff/requests',{method:'POST',body:JSON.stringify({id:item.id,action:'reject'})});await loadAdmin();render()}catch(err){notice(err.message)}});controls.append(role,position,approve,reject);card.append(info,controls);panel.append(card)});area.append(panel);const accounts=make('section','admin-panel');accounts.append(make('h2','',`Approved staff accounts (${(state.adminData.staff_accounts||[]).length})`));(state.adminData.staff_accounts||[]).forEach(item=>{const row=make('article','admin-item');const info=make('div');info.append(make('strong','',item.full_name||item.email),make('small','',`${item.email} · ${item.approved_position||item.role}${item.active?'':' · disabled'}`));row.append(info);row.append(btn(item.active?'Disable account':'Re-enable account','button button-secondary button-small',async()=>{if(item.active&&!confirm(`Disable sign-in for ${item.email}?`))return;try{await fetchJson('/api/admin/staff/accounts',{method:item.active?'DELETE':'POST',body:JSON.stringify({id:item.id,action:item.active?'disable':'enable'})});await loadAdmin();render()}catch(err){notice(err.message)}}));accounts.append(row)});area.append(accounts);const positions=make('section','admin-panel');positions.append(make('h2','', 'Leadership positions'));const form=make('form','admin-actions');const title=make('input');title.required=true;title.maxLength=120;title.placeholder='Position title';const add=make('button','button button-primary button-small','Add position');add.type='submit';form.append(title,add);form.addEventListener('submit',async e=>{e.preventDefault();try{await fetchJson('/api/admin/leadership-positions',{method:'POST',body:JSON.stringify({title:title.value})});await loadAdmin();render()}catch(err){notice(err.message)}});positions.append(form);(state.adminData.leadership_positions||[]).forEach(item=>{const row=make('article','admin-item');row.append(make('span','',`${item.title}${item.active?'':' · closed to new requests'}`));if(item.active)row.append(btn('Remove from applications','button button-secondary button-small',async()=>{try{await fetchJson('/api/admin/leadership-positions',{method:'DELETE',body:JSON.stringify({id:item.id})});await loadAdmin();render()}catch(err){notice(err.message)}}));positions.append(row)});positions.append(make('p','microcopy','Removing a position closes it to new applicants; it does not remove staff accounts that were already approved.'));area.append(positions);}
  function renderAdminTeam(area){const canManage=['CEO','President'].includes(state.admin.role);if(!canManage){area.append(make('div','notice-box',t('noPermission')));return}const panel=make('section','admin-panel');panel.append(make('h2','',t('teamTab')));const list=make('div','admin-list');state.adminData.team.forEach(p=>{const row=make('article','admin-item');const info=make('div');info.append(make('strong','',p.full_name),make('small','',`${p.position} · #${p.display_order}`));const actions=make('div','admin-actions');actions.append(btn(t('edit'),'button button-secondary button-small',()=>{state.editingTeam=p.id;render()}),btn(t('delete'),'button button-coral button-small',async()=>{if(!confirm(`${t('delete')} ${p.full_name}?`))return;try{await fetchJson('/api/admin/team',{method:'DELETE',body:JSON.stringify({id:p.id})});await loadAdmin();render()}catch(e){notice(e.message)}}));row.append(info,actions);list.append(row)});panel.append(list,btn(t('addProfile'),'button button-primary button-small',()=>{state.editingTeam='new';render()}));area.append(panel);if(state.editingTeam){const old=state.adminData.team.find(p=>p.id===state.editingTeam)||{};const form=make('form','admin-panel admin-form');form.append(make('h2','',old.id?t('edit'):t('addProfile')));const values={full_name:old.full_name||'',position:old.position||'',biography:old.biography||'',responsibility:old.responsibility||'',display_order:old.display_order||0};const inputs={};[["full_name",t('fullName'),false],["position",t('position'),false],["biography",t('biography'),true],["responsibility",t('responsibility'),true],["display_order",t('displayOrder'),false]].forEach(([key,label,isArea])=>{const f=make('div','form-field');const input=make(isArea?'textarea':'input');input.name=key;input.value=values[key];if(key==='display_order')input.type='number';const l=make('label','',label);l.htmlFor=`team-${key}`;input.id=`team-${key}`;f.append(l,input);form.append(f);inputs[key]=input});const feedback=make('p','muted');const save=make('button','button button-primary',t('save'));save.type='submit';form.append(save,feedback);form.addEventListener('submit',async e=>{e.preventDefault();try{await fetchJson('/api/admin/team',{method:'POST',body:JSON.stringify({id:old.id||undefined,full_name:inputs.full_name.value,position:inputs.position.value,biography:inputs.biography.value,responsibility:inputs.responsibility.value,display_order:Number(inputs.display_order.value),active:true})});state.editingTeam=null;await loadAdmin();render()}catch(err){feedback.textContent=err.message;feedback.className='error-text'}});area.append(form)}}
