  function render(){document.querySelectorAll('.main-nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===route()));main.replaceChildren();const page=route();let node;if(page==='home')node=homePage();else if(page==='learning')node=learningPage();else if(page==='services')node=servicesPage();else if(page==='help')node=helpPage();else if(page==='resources')node=resourcesPage();else if(page==='about')node=aboutPage();else if(page==='team')node=teamPage();else if(page==='privacy')node=privacyPage();else if(page==='contact')node=contactPage();else if(page==='donate')node=donatePage();else if(page==='search')node=searchPage();else if(page==='account')node=accountPage();else if(page==='staff')node=staffApplicationPage();else if(page==='admin'){if(!state.admin&&state.data?.admin){state.admin=state.data.admin;loadAdmin().then(render).catch(()=>{})}node=adminPage()}else node=homePage();main.append(node);if(state.humanRecorder?.owner&&!state.humanRecorder.owner.isConnected)humanCancelVoiceRecording();}
